/// <summary>
/// Overview tab activated
/// </summary>
/// <param name="sender">OverviewTab control</param>
/// <param name="e">FormControlEventArgs instance</param>
[FormControlEventHandler(formControlStr(GUPDiscountClaim, Overview), FormControlEventType::PageActivated),
 SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void Overview_OnPageActivated(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();
    METGUPDiscountClaimFormEventHandler::enableOrDisableActionPaneButtons(formRun, true);
}

/// <summary>
/// ClaimFeeTab Activated
/// </summary>
/// <param name="sender">ClaimFeeTab control</param>
/// <param name="e">FormControlEventArgs instance</param>
[FormControlEventHandler(formControlStr(GUPDiscountClaim, ClaimFeeTab), FormControlEventType::PageActivated),
 SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void ClaimFeeTab_OnPageActivated(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();
    METGUPDiscountClaimFormEventHandler::enableOrDisableActionPaneButtons(formRun, true);
}

/// <summary>
/// Vendor claim tab Activated
/// </summary>
/// <param name="sender">Vendor claim control</param>
/// <param name="e">FormControlEventArgs instance</param>
[FormControlEventHandler(formControlStr(GUPDiscountClaim, METVendorClaim), FormControlEventType::PageActivated),
 SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void METVendorClaim_OnPageActivated(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();
    METGUPDiscountClaimFormEventHandler::enableOrDisableActionPaneButtons(formRun, false);
}

/// <summary>
/// Enable or disable buttons on action pane
/// </summary>
/// <param name = "_formRun">GUPDiscountClaim formrun instance</param>
/// <param name = "_enableButtons">Enable or disable</param>
public static void enableOrDisableActionPaneButtons(FormRun _formRun, boolean _enableButtons)
{
    if (!_formRun)
    {
        return;
    }       

    GUPDiscountClaim discountClaim = _formRun.dataSource(formDataSourceStr(GUPDiscountClaim, GUPDiscountClaim)).cursor();

    if (discountClaim && _enableButtons)
    {
        _formRun.design().controlName(formControlStr(GUPDiscountClaim, GUPDiscountClaimAccrualJournal)).enabled(true);
        _formRun.design().controlName(formControlStr(GUPDiscountClaim, GUPDiscountClaimTransactionButton)).enabled(true);
    }
    else
    {
        _formRun.design().controlName(formControlStr(GUPDiscountClaim, GUPDiscountClaimAccrualJournal)).enabled(false);
        _formRun.design().controlName(formControlStr(GUPDiscountClaim, GUPDiscountClaimTransactionButton)).enabled(false);
    }
}
